const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/direct_costs',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[id]': 'SOME_ARRAY_VALUE',
    'filters[origin_id]': 'SOME_STRING_VALUE',
    'filters[invoice_number]': 'SOME_STRING_VALUE',
    'filters[created_at]': 'SOME_STRING_VALUE',
    'filters[updated_at]': 'SOME_STRING_VALUE',
    'filters[payment_date]': 'SOME_STRING_VALUE',
    'filters[received_date]': 'SOME_STRING_VALUE'
  },
  headers: {Authorization: 'Bearer REPLACE_BEARER_TOKEN'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/direct_costs?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Bid%5D=SOME_ARRAY_VALUE&filters%5Borigin_id%5D=SOME_STRING_VALUE&filters%5Binvoice_number%5D=SOME_STRING_VALUE&filters%5Bcreated_at%5D=SOME_STRING_VALUE&filters%5Bupdated_at%5D=SOME_STRING_VALUE&filters%5Bpayment_date%5D=SOME_STRING_VALUE&filters%5Breceived_date%5D=SOME_STRING_VALUE"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

